package agent

// 114-2 (owner 19 Nov 2026: "Skills sind auf Englisch"): the built-in
// skills in German. The agent app shows name, "when" and steps in the
// language of the page (de here, en from BuiltInSkills), and the agent's
// folder (Skills/TitanOS/, German like the rest of it) gets these. The
// model keeps reading the English steps with skill_read; tool names are
// the same in both (TestBuiltInSkillsGerman).

// SkillText is a skill in another language.
type SkillText struct {
	Name  string `json:"name"`
	When  string `json:"when"`
	Steps string `json:"steps"`
}

// BuiltInSkillsDE are the built-in skills in German, by id.
var BuiltInSkillsDE = map[string]SkillText{
	"builtin-service-status": {Name: "Status eines Dienstes", When: "\"Wie ist der Status von Home Assistant/Plex/…?\", läuft …?",
		Steps: "1. Überall nachsehen: docker_list, vm_list, lxc_list, bei Home Assistant zusätzlich ha_diagnostics.\n2. Mehrere Treffer: mit ask_user fragen, welcher gemeint ist, und „beide“ anbieten.\n3. Für jeden: Zustand, Laufzeit, Version und Updates, Adresse/Ports, letzte Sicherung, Warnungen in den Logs der letzten 24 h (container_logs / logs_search mit since 24h).\n4. Mit einer kleinen Tabelle antworten und in einem Satz sagen, was empfohlen wird."},
	"builtin-health": {Name: "Gesundheitscheck", When: "Gesundheitscheck, \"ist alles ok?\", regelmäßiger Bericht",
		Steps: "1. system_status, storage_overview, notifications, backup_status, update_status, disk_tests.\n2. docker_list (gestoppte oder ungesunde Container, Updates), vm_list und ha_diagnostics, wenn Home Assistant verbunden ist.\n3. Zuerst nur melden, was Aufmerksamkeit braucht (ausgefallene Platten, degradiertes RAID, überfällige Sicherungen, Volumes über 85 %, hohe Temperaturen, gestoppte Apps, Updates), dann eine Zeile „alles andere ist in Ordnung“. Nennen, was nicht geprüft werden konnte (agent_access)."},
	"builtin-slow": {Name: "Warum ist das NAS langsam?", When: "\"Warum ist das NAS langsam?\", hängt, Last, seit wann langsam",
		Steps: "1. system_status: CPU-Last, Arbeitsspeicher, Temperaturen im Moment.\n2. storage_overview: ob ein Rebuild oder eine Prüfung (Scrub) läuft, ob eine Platte Fehler hat; disk_tests: ob ein Test läuft.\n3. docker_list und vm_list: wer am meisten CPU und Arbeitsspeicher belegt.\n4. monitoring_history (hours 24, oder 168 bei \"seit Tagen\"): seit wann, und ob Plattenlatenz oder Netzwerk hoch sind. Ist es ausgeschaltet, das sagen.\n5. logs_search mit minLevel warning und since 6h für Fehler um diese Zeit.\n6. Zuerst mit der wahrscheinlichen Ursache antworten, dann die Belege und ein Schritt zur Behebung."},
	"builtin-night": {Name: "Was ist heute Nacht passiert?", When: "\"Was war heute Nacht?\", Morgenrückblick, \"was ist passiert?\", seit gestern",
		Steps: "1. Der Zeitraum: seit gestern 22:00 bis jetzt (oder was die Person sagt), als since/until.\n2. notifications; activity_log mit diesem Zeitraum; backup_status (sind die nächtlichen Jobs gelaufen?).\n3. logs_search mit minLevel warning und dem Zeitraum.\n4. Falls angeboten: ha_logbook (gelaufene Automationen, Türen) und nvr_events (Personen und Autos an den Kameras) für den Zeitraum.\n5. Nach Uhrzeit berichten, das Wichtigste zuerst, in wenigen Zeilen; sagen, was nicht angesehen werden konnte (hidden/why, agent_access)."},
	"builtin-full": {Name: "Wann sind die Platten voll?", When: "\"Wann ist die Platte voll?\", Speicherprognose, wie lange reicht der Platz",
		Steps: "1. storage_overview: Größe und Belegung jedes Volumes im Moment.\n2. capacity_forecast: Wachstum pro Tag und Tage bis 90 % und bis voll.\n3. Pro Volume mit einem Datum antworten (heute + Tage). Ist der Monitoring-Verlauf aus oder zu kurz, das sagen und wo er eingeschaltet wird (Einstellungen › Monitoring), statt zu raten."},
	"builtin-wrong": {Name: "Die Person sagt, die Antwort ist falsch", When: "\"Das stimmt nicht\", \"du siehst X nicht\", \"falsch\", Widerspruch",
		Steps: "1. Das Ergebnis ansehen, aus dem die Antwort stammt, und dieses Tool noch einmal aufrufen (mit demselben Filter).\n2. Darin hidden, why, note und total lesen; agent_access für die eigenen Rechte aufrufen (Home-Assistant-Freigabe, Ordnerregeln, abgeschaltete Dienste).\n3. Ist es nicht sichtbar: genau das sagen und wo die Person es freigibt. War die Antwort falsch: sagen, was falsch war, und die richtige Antwort geben.\n4. Nie Dateien nach Daten einer App durchsuchen (Home Assistant, Fotos, Kameras), und die Behauptung nicht mit memory_save speichern, bevor sie geprüft ist."},
	"builtin-whats-new": {Name: "Was ist neu?", When: "\"Was ist neu?\", Neuerungen, Changelog, was bringt die Version",
		Steps: "1. release_notes (area updates) für die laufende Version oder die Version, die die Person nennt.\n2. Die fünf nützlichsten Änderungen in einfachen Worten zusammenfassen, dann, was bekanntermaßen noch offen ist.\n3. Ohne Versionshinweise das sagen; nie Änderungen erfinden. Für eine neuere Version, die nicht installiert ist: update_status."},
	"builtin-where": {Name: "Wo stelle ich … ein?", When: "\"Wo stelle ich … ein?\", \"wie richte ich … ein?\", Einstellung finden",
		Steps: "1. docs_search mit dem deutschen und dem englischen Wort (z. B. \"Ruhemodus standby\").\n2. docs_read für den besten Abschnitt, wenn der Treffer kurz ist.\n3. Mit dem Pfad im Menü (Einstellungen › …) und den zwei oder drei Schritten antworten; anbieten, es selbst zu erledigen, wenn es ein Tool dafür gibt."},
	"builtin-access": {Name: "Was darfst du?", When: "\"Was darfst du?\", \"was siehst du nicht?\", Rechte des Agenten",
		Steps: "1. agent_access.\n2. In einfachen Worten antworten: was ohne Nachfrage erlaubt ist, was vorher nachfragt, was verboten oder nicht verfügbar ist und wo sich das jeweils ändern lässt."},
	"builtin-find-file": {Name: "Eine Datei finden", When: "Dokument, Rechnung, Datei suchen",
		Steps: "1. files_search in den wahrscheinlichen Freigaben mit ein paar markanten Wörtern (Namen, Jahreszahlen); files_list ohne root zeigt die Wurzeln.\n2. Vielversprechende Treffer mit file_read öffnen, um sie zu bestätigen.\n3. Die Treffer mit ihrem Ort auflisten; anbieten, sie zu kopieren oder zu sortieren."},
	"builtin-photos": {Name: "Fotos finden", When: "Fotos, Bilder vom Urlaub, Bilder von …",
		Steps: "1. photos_search (area photos) mit dem, was auf dem Bild ist, einer Person, einem Ort oder einem Zeitraum.\n2. Sind Fotos nicht verfügbar: agent_access sagt, warum (kein Immich-Schlüssel); das sagen, dann files_search mit extension images anbieten.\n3. In einem Satz sagen, was gefunden wurde; der Chat zeigt die Bilder."},
	"builtin-document": {Name: "Ein Dokument erstellen", When: "Word, Excel, PDF, Übersicht, Brief oder Liste erstellen",
		Steps: "1. Zuerst die Fakten mit Tools sammeln.\n2. Den Ort festlegen: was die Person gesagt hat, der Projektort, sonst der eigene Ordner in der Freigabe KI-Agent – nicht danach fragen.\n3. file_write: eine .docx oder .pdf mit dem Inhalt als Markdown (Überschriften, Tabellen), eine .xlsx mit ihren Tabellenblättern und Zeilen (Zahlen als Zahlen).\n4. Sagen, wo es liegt."},
	"builtin-backup": {Name: "Stand der Sicherungen", When: "Backup-Stand, \"sind meine Sicherungen ok?\"",
		Steps: "1. backup_status; bei Problemen backup_snapshots und backup_check.\n2. Pro Job berichten: Ziel, letzter Erfolg, nächster Lauf, überfällig oder fehlgeschlagen.\n3. Für Fehlschläge eine Lösung vorschlagen. Sicherungen von Home Assistant und Snapshots von VMs sind nicht in backup_status; das auf Nachfrage sagen."},
	"builtin-cleanup": {Name: "Speicherplatz freigeben", When: "Speicher aufräumen, Volume voll, was belegt am meisten Platz",
		Steps: "1. storage_overview für das vollste Volume.\n2. files_search in seinen Freigaben mit minSize (z. B. 500 MB) und sort size für große Dateien (Videos, ISOs, Archive).\n3. Zeigen, was wegkönnte, das Größte zuerst, mit Größen. Welche Dateien gelöscht werden, entscheidet die Person: mit files_delete (in den Papierkorb) löschen, was der Auftrag oder ihre Antwort genannt hat."},
	"builtin-research": {Name: "Ein Thema im Web recherchieren", When: "Recherche, \"finde heraus\", \"vergleiche\", aktuelle Fakten aus dem Internet",
		Steps: "1. plan_update mit den Fragen, die zu beantworten sind.\n2. web_search drei- bis fünfmal mit verschiedenen Wörtern (auch auf Englisch); nicht beim ersten Treffer aufhören.\n3. web_read für die vier bis sechs besten Seiten – die eigenen Seiten des Herstellers, Dokumentation und Tests gegenüber Shops und Foren bevorzugen. Bei jedem Fakt notieren, wo er steht.\n4. Wo Quellen sich widersprechen, das sagen, statt eine auszuwählen.\n5. Zuerst mit dem Ergebnis antworten, dann die Details in kurzen Abschnitten oder einer Tabelle und am Ende die Liste \"Quellen\" mit Titel und Adresse jeder verwendeten Seite. Nie eine Quelle nennen, die nicht gelesen wurde.\n6. Ein längeres Ergebnis als Word-Dokument anbieten (file_write, .docx)."},
	"builtin-edit-document": {Name: "Eine Word- oder Excel-Datei ändern", When: "vorhandene .docx oder .xlsx ändern: Zellen, Zeilen, Formeln, Text",
		Steps: "1. Das Dokument mit file_read lesen, um zu sehen, was darin steht.\n2. Kleine Änderungen – Zellen setzen, genauen Text ersetzen – mit document_edit; das erhält das Layout.\n3. Alles Weitere (Zeilen oder Spalten einfügen, Formeln, Sortieren, neue Tabellenblätter, Tabellen in Word): die Datei mit file_copy in den eigenen Ordner in der Freigabe KI-Agent kopieren, dann code_run mit openpyxl oder python-docx auf /work/<name>, unter einem neuen Namen speichern und ausgeben, was geändert wurde.\n4. Das Ergebnis mit file_read prüfen.\n5. Es mit file_copy und einem klaren Namen neben das Original legen (z. B. \"… (bearbeitet)\"); das Original nie überschreiben, außer die Person hat es gesagt.\n6. Sagen, was geändert wurde und wo die Datei liegt."},
	"builtin-pdf": {Name: "PDFs zusammenfügen, teilen oder lesen", When: "PDFs zusammenfügen, teilen, Seiten herausnehmen, Text aus einem PDF",
		Steps: "1. Die PDFs mit file_copy in den eigenen Ordner in der Freigabe KI-Agent kopieren.\n2. code_run mit pypdf: PdfWriter zum Zusammenfügen oder zum Herausnehmen von Seiten, PdfReader zum Lesen des Texts der Seiten. Die Seitenzahl des Ergebnisses ausgeben.\n3. Das Ergebnis mit file_copy dorthin kopieren, wo die Person es haben möchte (sonst neben das erste PDF).\n4. Sagen, wo es liegt und wie viele Seiten es hat."},
	"builtin-summarize": {Name: "Ein Dokument zusammenfassen", When: "Zusammenfassen, \"was steht in …?\"",
		Steps: "1. Das Dokument mit file_read lesen; ein langes Teil für Teil.\n2. Zuerst mit den drei bis fünf Punkten antworten, auf die es ankommt, dann die Details nach Abschnitten. Zahlen, Daten und Namen genau so wiedergeben, wie sie dastehen.\n3. Sagen, was nicht gelesen werden konnte (ein Scan ohne Text, fehlende Seiten)."},
	"builtin-table": {Name: "Eine Tabelle auswerten", When: "Excel oder CSV auswerten, Summen, \"wie viel … pro Monat?\"",
		Steps: "1. Die .xlsx oder .csv mit file_read lesen, um die Spalten und einige Zeilen zu sehen.\n2. Eine kleine Tabelle: aus dem Gelesenen rechnen und den Rechenweg zeigen. Eine große: mit file_copy in den eigenen Ordner in der Freigabe KI-Agent kopieren und code_run mit openpyxl oder dem csv-Modul; die Zahlen ausgeben.\n3. Mit den Zahlen in einer kleinen Tabelle antworten und einem Satz dazu, was auffällt.\n4. Das Ergebnis nur dann in ein neues Tabellenblatt oder eine neue Datei schreiben, wenn das verlangt wurde."},
	"builtin-ha-automations": {Name: "Automationen in Home Assistant", When: "\"Wie viele Automationen?\", welche liefen heute, Automation ein/aus",
		Steps: "1. ha_entities mit domain automation: Anzahl, Zustand (on/off) und lastTriggered. Sagt hidden/why, dass sie nicht freigegeben sind, das sagen und wo (keine Anzahl).\n2. Welche in einem Zeitraum liefen: ha_logbook mit since/until.\n3. Die Einstellungen einer Automation: ha_config_read.\n4. Eine ein- oder ausschalten oder auslösen: ha_call (TitanOS fragt die Person vorher)."},
	"builtin-ha-automation": {Name: "Automation in Home Assistant anlegen oder ändern", When: "Automation anlegen oder ändern, \"wenn … dann …\", Zeitschaltung, Bewegungsmelder schaltet Licht",
		Steps: "1. Mit ha_entities die genauen Entitäten für den Auslöser und das Ziel finden; nie eine Entity-ID raten.\n2. Zum Ändern: die Automation zuerst mit ha_config_read lesen und beibehalten, was nicht geändert werden soll.\n3. Klein halten: ein Auslöser, Bedingungen nur auf Wunsch, die Aktionen.\n4. ha_automation_save mit einem klaren deutschen Namen; das Ergebnis enthält die vorherige Version, falls es eine gab.\n5. ha_state der Automation, um zu bestätigen, dass sie vorhanden und eingeschaltet ist. In zwei Sätzen sagen, was sie tut und wie man sie ausschaltet."},
	"builtin-disk-swap": {Name: "Eine Platte tauschen", When: "Platte tauschen, Platte defekt, \"welche Platte muss raus?\"",
		Steps: "1. storage_overview und disk_tests: welche Platte ausfällt, ihre Seriennummer und ihr Schacht, zu welchem Volume sie gehört.\n2. backup_status: gibt es eine frische Sicherung? Wenn nicht, zuerst eine vorschlagen.\n3. Schritt für Schritt erklären: ausschalten oder im laufenden Betrieb tauschen (Hot Swap), welche Seriennummer herausgezogen wird, wo der Rebuild gestartet wird (Seite Speicher).\n4. Nach dem Tausch: storage_overview, bis der Rebuild läuft; den Fortschritt melden."},
	"builtin-raid": {Name: "Den RAID-Zustand erklären", When: "RAID degradiert, Rebuild, \"ist mein RAID ok?\"",
		Steps: "1. storage_overview für jedes Volume: Level, Mitglieder, Zustand, Sync-Fortschritt, Abweichungen.\n2. In einfachen Worten erklären, was der Zustand bedeutet und wie sicher die Daten gerade sind.\n3. Den einen nächsten Schritt nennen (auf den Rebuild warten, eine Platte tauschen, eine Prüfung starten)."},
	"builtin-smart": {Name: "SMART-Werte lesen", When: "SMART, Plattengesundheit, Plattentemperatur, \"wie alt sind meine Platten?\"",
		Steps: "1. storage_overview: für jede Platte SMART-Zustand, Temperatur, Fehler, Verschleiß und Betriebsstunden; disk_tests für die Selbsttests.\n2. Kennzeichnen, was bedenklich ist und was für ihr Alter normal ist.\n3. Für eine Platte, die schlecht aussieht, disk_test anbieten."},
	"builtin-container-updates": {Name: "Container-Updates prüfen", When: "Updates für Docker/Apps, \"welche Container brauchen ein Update?\"",
		Steps: "1. docker_list: welche Container ein Update haben. Will die Person, dass jetzt geprüft wird, docker_check_updates (sieht nur nach, ändert nichts), dann erneut docker_list.\n2. Für jeden: aktuelle und neue Version; die Versionshinweise mit web_read lesen, wenn Internet erlaubt ist.\n3. Sagen, was jetzt installiert werden sollte und warum. War der Auftrag, zu aktualisieren, das mit app_action oder apps_update_all tun und danach docker_list prüfen; war es nur eine Frage, bei der Empfehlung aufhören."},
	"builtin-app-setup": {Name: "Eine App aus dem Katalog einrichten", When: "\"installier mir …\", neue App, App einrichten",
		Steps: "1. Fragen, wofür sie gedacht ist, falls unklar; mit docker_list nachsehen, ob sie schon läuft.\n2. Erklären, wo sie ihre Daten ablegen wird (locations_list, shares_list) und welchen Port sie bekommt.\n3. Die Person zu Apps › der App schicken, um sie dort zu installieren (der Agent installiert Katalog-Apps nicht selbst); danach mit docker_list und container_logs prüfen."},
	"builtin-logs": {Name: "Logs nach Fehlern durchsuchen", When: "Fehler finden, \"warum stürzt … ab?\", Logs",
		Steps: "1. logs_search mit dem Dienst oder Fehlerwörtern und since (z. B. 24h); container_logs für Apps.\n2. Wiederholte Zeilen gruppieren, das erste und letzte Auftreten zeigen.\n3. Die wahrscheinliche Ursache und eine Lösung erklären."},
	"builtin-vm": {Name: "Eine VM sicher starten oder stoppen", When: "VM starten, stoppen, neu starten",
		Steps: "1. vm_list: Zustand und was darin läuft (Beschreibung aus nas_map).\n2. vm_action mit start, shutdown oder reboot wie gewünscht; vor einem Stopp oder Neustart in einem Satz sagen, was offline geht.\n3. Erneut vm_list prüfen und berichten."},
	"builtin-lxc": {Name: "Systemcontainer (LXC)", When: "LXC, Systemcontainer",
		Steps: "1. lxc_list: Zustand, Adresse, Ressourcen.\n2. Mit lxc_action wie gewünscht handeln.\n3. Den neuen Zustand melden."},
	"builtin-share": {Name: "Eine Freigabe erstellen", When: "neue Freigabe, Ordner fürs Netzwerk",
		Steps: "1. shares_list und storage_overview: ob der Name frei ist, welches Volume Platz hat.\n2. share_create; das Konto, das sie anlegt, darf lesen und schreiben.\n3. Sagen, wie man sich verbindet (SMB-Pfad) und dass weitere Konten unter Freigaben › der Freigabe Zugriff bekommen."},
	"builtin-accounts": {Name: "Konten und Zugriff", When: "Konten, Rollen, \"wer darf was?\"",
		Steps: "1. accounts_list und shares_list: Rollen und Freigaben.\n2. In einer kleinen Tabelle zeigen, wer was darf.\n3. Rollenänderungen und das Löschen eines Kontos: account_action. Für Rechte auf einer Freigabe (\"gib Anna Zugriff\") gibt es kein Tool: die Person setzt sie unter Freigaben › der Freigabe. Passwörter setzt die Person selbst, nie der Agent."},
	"builtin-network": {Name: "Netzwerkprobleme", When: "Netzwerk langsam, nicht erreichbar, DNS",
		Steps: "1. network_status und network_diagnostics.\n2. firewall_status, wenn etwas blockiert wird.\n3. Den Befund und den nächsten Schritt erklären."},
	"builtin-firewall": {Name: "Firewall-Regeln", When: "Firewall, Port freigeben, gesperrt",
		Steps: "1. firewall_status: Zonen, Regeln, gesperrte Adressen.\n2. Die Regel wie gewünscht mit firewall_rule_add hinzufügen oder mit firewall_unblock entsperren und in einem Satz sagen, was jetzt offen ist.\n3. Die Admin-Seite nie zum Internet hin öffnen."},
	"builtin-updates": {Name: "Systemupdates", When: "TitanOS-Update, \"gibt es ein Update?\"",
		Steps: "1. update_status: running ist die Version, die jetzt läuft (nie systemImageBase oder fallbackSystems), upToDate, newest; dessen Antwortsatz übernehmen und TitanOS nie als aktuell bezeichnen, wenn checkError gesetzt ist oder nichts geprüft wurde. Eine alte Prüfung: update_action check (sieht nur nach).\n2. Zusammenfassen, was sich ändert; backup_status prüfen und sicherstellen, dass kein langer Vorgang läuft.\n3. War der Auftrag, zu aktualisieren: sagen, dass das NAS dabei neu starten kann, dann update_action install. War es nur eine Frage, bei der Zusammenfassung aufhören. Apps: siehe den Skill für Container-Updates."},
	"builtin-power": {Name: "Energie und Ruhemodus", When: "Strom sparen, Platten schlafen, Ruhemodus",
		Steps: "1. storage_overview (Platten, Temperaturen, welcher Ruhemodus) und ups_status.\n2. Was die Platten wach hält (laufende Apps, Scans): docker_list, logs_search mit since 24h.\n3. Wo es eingestellt wird: docs_search \"Ruhemodus Energie\", dann den Ort nennen (Einstellungen › Energie)."},
	"builtin-ups": {Name: "USV-Zustand", When: "USV, Stromausfall",
		Steps: "1. ups_status: Netz- oder Batteriebetrieb, Ladung, Laufzeit.\n2. Erklären, was bei niedrigem Batteriestand passiert.\n3. Den letzten Stromausfall aus notifications erwähnen."},
	"builtin-notifications": {Name: "Meldungen erklären", When: "\"was bedeutet die Meldung?\", Meldungen",
		Steps: "1. notifications: die letzten mit Uhrzeit und Art (seit dem letzten Start aufbewahrt; ältere: activity_log).\n2. Für jede: was sie bedeutet und ob gehandelt werden muss.\n3. Mit der wichtigsten beginnen."},
	"builtin-snapshots": {Name: "Aus einer Sicherung wiederherstellen", When: "Datei wiederherstellen, gelöscht, alte Version",
		Steps: "1. backup_snapshots für den Job, der den Ort abdeckt; backup_files, um die Datei zu finden.\n2. Passende Versionen mit Datum und Größe zeigen.\n3. Ein eindeutiger Treffer: mit backup_restore_files in einen neuen Ordner wiederherstellen, nie über das Original. Mehrere Versionen: fragen, welche."},
	"builtin-invoices": {Name: "Rechnungen sortieren", When: "Rechnungen ablegen, Belege sortieren",
		Steps: "1. files_search nach PDFs und Scans in den üblichen Eingangsordnern; document_read, um Absender, Datum und Betrag zu lesen.\n2. Zielordner nach Absender und Jahr vorschlagen (locations_list).\n3. files_move in diese Ordner; auflisten, was wohin verschoben wurde. Was nicht gelesen werden konnte, liegen lassen und das sagen."},
	"builtin-duplicates": {Name: "Doppelte Dateien finden", When: "doppelte Dateien, Duplikate",
		Steps: "1. files_search in den gewählten Orten (sort size); nach Name und Größe gruppieren.\n2. Gruppen mit Gesamtgröße zeigen; die Kopie am sinnvollsten Ort behalten.\n3. Welche Kopien wegkommen, entscheidet die Person, außer der Auftrag hat es gesagt; dann files_delete (in den Papierkorb)."},
	"builtin-home": {Name: "Ist zu Hause alles zu?", When: "Fenster/Türen zu, abgeschlossen, Alarmanlage, abends",
		Steps: "1. ha_entities mit device_class window,door,garage_door; dann domain lock und domain alarm_control_panel.\n2. Nur auflisten, was offen oder nicht abgeschlossen ist, nach Raum. Eine Art mit hidden/why ist nicht freigegeben: sagen, dass sie nicht sichtbar ist, nie „alles zu“.\n3. Sagt der Auftrag, zu schließen oder abzuschließen: ha_call für jedes, dann erneut ha_entities zur Bestätigung."},
	"builtin-energy-ha": {Name: "Energie zu Hause", When: "Stromverbrauch heute, PV, Energie in Home Assistant",
		Steps: "1. ha_entities mit device_class energy (oder Suche \"energy\") für die Energiesensoren.\n2. ha_statistics für heute und gestern.\n3. Vergleichen, die größten Verbraucher nennen und einen Spartipp geben."},
	"builtin-cameras": {Name: "Wer war an der Tür?", When: "Kamera, Klingel, \"wer war da?\", Bewegung am Haus",
		Steps: "1. nvr_events (area nvr) mit der Kamera und dem Zeitraum (since/until).\n2. Mit Uhrzeiten und dem Gesehenen antworten (Person, Auto …). Namen kommen nur, wenn die Person sie erlaubt hat; nie einen Namen raten. Keine Bilder: dafür auf die NVR-App verweisen."},
	"builtin-reminder": {Name: "Aufgabe oder Erinnerung planen", When: "\"erinnere mich …\", \"mach jeden Montag …\", Erinnerung löschen",
		Steps: "1. Verstehen, was, wann und wie oft; bei Unklarheit einmal fragen. Ein Gerät, das jedes Mal von selbst schalten soll, ist stattdessen eine Home-Assistant-Automation.\n2. schedule_create mit dem passenden kind (reminder ohne das Modell, task mit dem Modell).\n3. Mit der nächsten Ausführungszeit bestätigen; schedule_list zeigt die anderen, schedule_delete nimmt eine zurück."},
	"builtin-mail-write": {Name: "Eine Mail schreiben oder senden", When: "\"Schreib/schick eine Mail an …\", antworten, weiterleiten",
		Steps: "1. Empfänger: die Adresse, die die Person genannt hat, oder contacts_search für einen Namen (zuerst tools_load contacts); mehrere Treffer: mit ask_user fragen, welcher; keiner: nach der Adresse fragen.\n2. Betreff und Text: übernehmen, was die Person gesagt hat, und mit ask_user nach dem Fehlenden fragen; nie Inhalte erfinden. Eine Antwort: die Mail mit mail_search oder mail_list finden, mit mail_read lesen und reply angeben.\n3. mail_send, oder mail_draft, wenn die Person sie ungesendet behalten will. Kommt sie als Karte zurück (\"Nur Vorschläge\"), das einmal sagen und aufhören.\n4. In einem Satz bestätigen: an wen, der Betreff und ob sie gesendet oder gespeichert wurde oder als Karte wartet."},
	"builtin-event-create": {Name: "Einen Termin eintragen", When: "\"Trag mir … ein\", Termin am …, \"blocke mir …\"",
		Steps: "1. Titel, Tag, Uhrzeit und Dauer aus der Nachricht (\"morgen um 10\" ist das Datum von morgen; keine Dauer: eine Stunde; ein ganzer Tag ohne Uhrzeit: ganztägig). Nur dann mit ask_user fragen, wenn der Tag unklar ist.\n2. calendar_list für diesen Tag: eine Überschneidung nennen und fragen, ob der Termin trotzdem eingetragen werden soll. \"Wann habe ich Zeit?\" ist calendar_free.\n3. calendar_create mit Titel und Beginn (Ende, Ort und Notizen nur, wenn bekannt).\n4. Mit Wochentag, Datum und Uhrzeit bestätigen, oder sagen, dass die Karte wartet, wenn daraus ein Entwurf wurde."},
	"builtin-contact-find": {Name: "Einen Kontakt finden", When: "Telefonnummer, Adresse oder Mail von …, \"wer ist …\"",
		Steps: "1. contacts_search mit dem Namen (ein Teil davon oder die Firma geht auch).\n2. Mehrere Treffer: eine kleine Tabelle mit Name und Firma, und fragen, welcher gemeint ist, wenn der Auftrag einen braucht. Keiner: das sagen und anbieten, ihn anzulegen (contacts_create).\n3. Genau mit dem antworten, was gefragt wurde (Nummer, Adresse, Mail), nicht mit dem ganzen Kontakt."},
}
